import{_ as t,o as d,c as o,a2 as a}from"./chunks/framework.Ch4PdLd_.js";const u=JSON.parse('{"title":"终端界面与输入","description":"","frontmatter":{},"headers":[],"relativePath":"guide/usage.md","filePath":"guide/usage.md"}'),c={name:"guide/usage.md"};function r(s,e,i,l,n,h){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="终端界面与输入" tabindex="-1">终端界面与输入 <a class="header-anchor" href="#终端界面与输入" aria-label="Permalink to &quot;终端界面与输入&quot;">​</a></h1><p>这一页讲交互模式下的日常操作：怎么输入、怎么引用文件、怎么在 nek 工作时插话、怎么滚动和搜索对话、怎么导出结果。</p><p>还没装好或没连模型？先看 <a href="/nekcode/start/quickstart">快速上手</a>。</p><h2 id="界面组成" tabindex="-1">界面组成 <a class="header-anchor" href="#界面组成" aria-label="Permalink to &quot;界面组成&quot;">​</a></h2><table tabindex="0"><thead><tr><th>区域</th><th>内容</th></tr></thead><tbody><tr><td>启动信息</td><td>版本、常用按键，以及加载到的指令文件、Skills、提示词模板、扩展、主题。按 <code>Ctrl+O</code> 展开完整列表。可用设置 <code>quietStartup</code> 隐藏</td></tr><tr><td>对话记录</td><td>你的消息、模型回复、思考过程、工具调用和结果、错误</td></tr><tr><td>编辑器上方</td><td>Todo 列表、运行中的后台子代理、扩展添加的小部件</td></tr><tr><td>输入框</td><td>输入提示词和命令。边框颜色表示当前思考等级；Plan 模式下换成专用颜色并显示 <code>PLAN</code> 标记</td></tr><tr><td>状态栏（footer）</td><td>当前目录和会话名、本会话累计的 token 用量和费用、上下文用量、当前模型和思考等级</td></tr></tbody></table><p>状态栏里的上下文用量显示为进度条，例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>▕████▌     ▏ 45.2% 90k/200k (auto)</span></span></code></pre></div><p>表示当前上下文约 90k token，模型上限 200k，<code>(auto)</code> 表示自动压缩已开启。超过 70% 变成警告色，超过 90% 变成错误色。终端宽度小于 70 列时只显示文字。</p><h2 id="输入提示词" tabindex="-1">输入提示词 <a class="header-anchor" href="#输入提示词" aria-label="Permalink to &quot;输入提示词&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>按键</th></tr></thead><tbody><tr><td>发送</td><td><code>Enter</code></td></tr><tr><td>换行</td><td><code>Shift+Enter</code>（或 <code>Ctrl+J</code>）</td></tr><tr><td>用外部编辑器写长提示词</td><td><code>Ctrl+G</code></td></tr><tr><td>浏览之前发过的提示词</td><td>输入框为空或光标在首行/末行时按 <code>↑</code> / <code>↓</code></td></tr><tr><td>清空输入框</td><td><code>Ctrl+C</code></td></tr><tr><td>退出 nek</td><td>连按两次 <code>Ctrl+C</code>，或输入框为空时按 <code>Ctrl+D</code>，或 <code>/quit</code></td></tr></tbody></table><p>外部编辑器按 <code>externalEditor</code> 设置、<code>$VISUAL</code>、<code>$EDITOR</code> 的顺序选择，都没有时 Windows 用记事本、其他系统用 <code>nano</code>。</p><p>如果 <code>Shift+Enter</code> 直接发送了消息，说明终端没有把修饰键传给 nek，见 <a href="/nekcode/platform/terminal-setup">终端设置</a>。</p><p>输入框支持完整的行编辑快捷键（按词移动、<code>Ctrl+W</code> 删词、<code>Ctrl+K</code> 删到行尾、<code>Ctrl+Y</code> 粘贴刚删除的内容、撤销等），见 <a href="/nekcode/reference/keybindings">快捷键</a>。</p><h2 id="files" tabindex="-1">引用文件和图片 <a class="header-anchor" href="#files" aria-label="Permalink to &quot;引用文件和图片 {#files}&quot;">​</a></h2><ul><li>输入 <code>@</code> 后接文件名片段，会弹出模糊搜索的文件列表，选中后插入路径。被 <code>@</code> 引用的文件内容会随消息一起发送。</li><li>按 <code>Tab</code> 补全路径。</li><li>粘贴图片：<code>Ctrl+V</code>（Windows/WSL 为 <code>Alt+V</code>）从剪贴板粘贴图片，剪贴板里是文字时粘贴文字。</li><li>在支持的终端里，也可以把图片文件拖进窗口。</li></ul><p>大段粘贴的文本在输入框里会折叠成一个标记，发送时展开为完整内容。</p><p>图片发送前默认缩放到不超过 2000×2000 像素（设置 <code>images.autoResize</code>）；不想发图片给模型可以设置 <code>images.blockImages: true</code>。</p><h2 id="斜杠命令" tabindex="-1">斜杠命令 <a class="header-anchor" href="#斜杠命令" aria-label="Permalink to &quot;斜杠命令&quot;">​</a></h2><p>输入 <code>/</code> 会弹出命令列表，可以继续输入进行搜索。常用的有：</p><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/model</code></td><td>切换模型</td></tr><tr><td><code>/thinking</code></td><td>设置思考等级</td></tr><tr><td><code>/login</code>、<code>/logout</code></td><td>添加或移除服务商凭据</td></tr><tr><td><code>/settings</code></td><td>打开设置</td></tr><tr><td><code>/plan</code>、<code>/agent</code></td><td>进入 Plan 模式、回到 Agent 模式</td></tr><tr><td><code>/todos</code>、<code>/subagents</code></td><td>查看 Todo 列表、管理子代理</td></tr><tr><td><code>/new</code>、<code>/resume</code></td><td>新会话、切换会话</td></tr><tr><td><code>/compact</code></td><td>手动压缩上下文</td></tr><tr><td><code>/mcp</code></td><td>管理 MCP 服务器</td></tr><tr><td><code>/hotkeys</code></td><td>查看当前生效的快捷键</td></tr></tbody></table><p>完整列表见 <a href="/nekcode/reference/slash-commands">斜杠命令</a>。扩展、提示词模板和 Skills 也会添加命令，<code>/</code> 菜单就是你当前会话可用命令的准确清单。</p><h2 id="观察-nek-的工作" tabindex="-1">观察 nek 的工作 <a class="header-anchor" href="#观察-nek-的工作" aria-label="Permalink to &quot;观察 nek 的工作&quot;">​</a></h2><p>nek 工作时，对话记录里会实时显示每个工具调用和结果：</p><ul><li><code>Ctrl+O</code>：展开或折叠工具输出（以及启动信息）。折叠时只显示前几行预览。</li><li><code>Ctrl+T</code>：显示或隐藏思考过程。</li><li><code>Shift+Tab</code>：在当前模型支持的思考等级之间切换。</li><li>子代理以卡片形式显示，运行中的卡片会实时更新当前活动，见 <a href="/nekcode/guide/subagents#display">子代理</a>。</li></ul><p>nek <strong>不会</strong>在每次调用工具前征求同意。请检查它执行的命令和改动的文件，不可信或无人值守的任务请使用沙箱，见 <a href="/nekcode/guide/security">安全使用</a>。</p><h2 id="steer" tabindex="-1">运行中插话或中止 <a class="header-anchor" href="#steer" aria-label="Permalink to &quot;运行中插话或中止 {#steer}&quot;">​</a></h2><p>nek 工作时你可以继续输入：</p><table tabindex="0"><thead><tr><th>想做的事</th><th>操作</th></tr></thead><tbody><tr><td>调整当前任务（插话）</td><td>输入消息后按 <code>Enter</code>。消息在当前这一轮的工具执行完后送达，模型下一步就会看到</td></tr><tr><td>当前任务完成后再做另一件事（追加）</td><td>输入消息后按 <code>Alt+Enter</code>（Windows/WSL 为 <code>Ctrl+Q</code>）</td></tr><tr><td>把排队中的消息拿回输入框</td><td><code>Alt+↑</code>（Windows/WSL 为 <code>Alt+Q</code>）</td></tr><tr><td>停止当前任务</td><td><code>Escape</code>。排队中的消息会退回输入框</td></tr></tbody></table><p>排队的消息默认每轮送达一条，可以用设置 <code>steeringMode</code>、<code>followUpMode</code> 改成一次全部送达。</p><p>压缩进行中按 <code>Enter</code> 输入的消息会在压缩完成后送达。</p><p>子代理运行期间（前台等待或 <code>await</code> 等待中），你发送的插话会结束等待：前台子代理转到后台继续运行，完成后发来通知。</p><h2 id="双击-escape" tabindex="-1">双击 Escape <a class="header-anchor" href="#双击-escape" aria-label="Permalink to &quot;双击 Escape&quot;">​</a></h2><p>输入框为空时连按两次 <code>Escape</code>，默认打开 <code>/tree</code>（会话树）。可以用设置 <code>doubleEscapeAction</code> 改为打开 <code>/fork</code>，或设为 <code>none</code> 关闭。</p><h2 id="执行终端命令" tabindex="-1">执行终端命令 <a class="header-anchor" href="#执行终端命令" aria-label="Permalink to &quot;执行终端命令&quot;">​</a></h2><p>在输入框里以 <code>!</code> 开头，直接执行一条 shell 命令，并把命令和输出加入对话：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>!git status</span></span></code></pre></div><p>以 <code>!!</code> 开头则只执行、不把输出发给模型：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>!!npm run dev</span></span></code></pre></div><p>这两种命令使用与 <code>bash</code> 工具相同的 Bash（Windows 上默认是 Git Bash），也会应用 <code>shellCommandPrefix</code> 设置，见 <a href="/nekcode/platform/shell">Shell 命令配置</a>。命令输出会在下一次你发送消息时一起交给模型。</p><h2 id="fullscreen" tabindex="-1">全屏模式与滚动 <a class="header-anchor" href="#fullscreen" aria-label="Permalink to &quot;全屏模式与滚动 {#fullscreen}&quot;">​</a></h2><p>nek 默认以全屏模式运行：输入框和状态栏固定在底部，对话记录由 nek 自己滚动。</p><table tabindex="0"><thead><tr><th>操作</th><th>按键</th></tr></thead><tbody><tr><td>翻页</td><td><code>PageUp</code> / <code>PageDown</code>，或鼠标滚轮</td></tr><tr><td>跳到开头 / 回到最新并跟随输出</td><td><code>Home</code> / <code>End</code></td></tr><tr><td>跳到上一条 / 下一条你的消息</td><td><code>Ctrl+Shift+↑</code> / <code>Ctrl+Shift+↓</code>（Windows/WSL 也可用 <code>Ctrl+↑</code> / <code>Ctrl+↓</code>）</td></tr><tr><td>搜索对话记录</td><td><code>Ctrl+Shift+F</code>（Windows/WSL 为 <code>Ctrl+F</code>），<code>Enter</code>/<code>Shift+Enter</code> 下一个/上一个，<code>Escape</code> 关闭</td></tr><tr><td>选择文字</td><td>鼠标拖选；默认选中即复制（设置 <code>fullscreenCopyOnSelect</code>）</td></tr></tbody></table><p>向上滚动后，nek 停止自动跟随新输出；按 <code>End</code> 回到底部并恢复跟随。</p><p>相关设置：</p><ul><li><code>fullscreenScrollbar</code>：滚动条 <code>auto</code>（默认）/<code>always</code>/<code>hidden</code>；</li><li><code>fullscreenExitOutput</code>：退出全屏时，<code>transcript</code>（默认）把对话记录打印到终端，<code>resume-hint</code> 只打印续接提示。</li></ul><h3 id="改用普通模式" tabindex="-1">改用普通模式 <a class="header-anchor" href="#改用普通模式" aria-label="Permalink to &quot;改用普通模式&quot;">​</a></h3><p>普通（regular）模式把对话直接输出到终端里，使用终端自己的滚动条、回滚记录和搜索：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nek</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tui-mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> regular</span></span></code></pre></div><p>想长期使用，在 <code>/settings</code> 里把 TUI mode 改成 regular，或在 <code>~/.nek/agent/settings.json</code> 中设置：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;tuiMode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;regular&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>在 tmux 里用鼠标滚轮需要先 <code>set -g mouse on</code>，见 <a href="/nekcode/platform/tmux">在 tmux 中运行</a>。</p><h2 id="切换模型和设置" tabindex="-1">切换模型和设置 <a class="header-anchor" href="#切换模型和设置" aria-label="Permalink to &quot;切换模型和设置&quot;">​</a></h2><ul><li><code>/model</code> 或 <code>Ctrl+L</code>：打开模型选择器。</li><li><code>Ctrl+P</code> / <code>Shift+Ctrl+P</code>（Windows/WSL 为 <code>Alt+P</code>）：在可用模型间循环切换。用 <code>/scoped-models</code> 限定循环范围。</li><li><code>/thinking</code> 或 <code>Shift+Tab</code>：调整思考等级。</li><li><code>/settings</code>：修改常用设置（主题、TUI 模式、压缩、排队方式等）。</li></ul><p>见 <a href="/nekcode/guide/models">选择模型</a> 和 <a href="/nekcode/reference/settings">settings.json</a>。</p><h2 id="继续或重新开始" tabindex="-1">继续或重新开始 <a class="header-anchor" href="#继续或重新开始" aria-label="Permalink to &quot;继续或重新开始&quot;">​</a></h2><p>nek 会自动保存会话（除非用 <code>--no-session</code> 启动）。</p><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/new</code></td><td>开始新会话</td></tr><tr><td><code>/resume</code></td><td>打开会话列表，切换到别的会话</td></tr><tr><td><code>/name &lt;名字&gt;</code></td><td>给当前会话起个好认的名字</td></tr><tr><td><code>/session</code></td><td>查看会话文件、ID、消息数、token 用量和费用</td></tr><tr><td><code>/tree</code>、<code>/fork</code>、<code>/clone</code></td><td>在不丢失现有工作的前提下尝试另一条路线</td></tr><tr><td><code>/compact</code></td><td>手动压缩上下文</td></tr></tbody></table><p>退出后在同一目录运行 <code>nek -c</code> 继续最近的会话。详见 <a href="/nekcode/guide/sessions">会话与上下文</a>。</p><h2 id="export" tabindex="-1">复制、导出与分享 <a class="header-anchor" href="#export" aria-label="Permalink to &quot;复制、导出与分享 {#export}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td><code>Ctrl+X</code> 或 <code>/copy</code></td><td>复制最后一条助手回复</td></tr><tr><td><code>/export [路径]</code></td><td>导出当前会话。默认 HTML；路径以 <code>.jsonl</code> 结尾时导出 JSONL</td></tr><tr><td><code>/share</code></td><td>上传会话并返回查看链接。登录了 Radius 时上传到 Radius；否则通过 GitHub CLI 创建一个私密 gist（需要先 <code>gh auth login</code>）</td></tr><tr><td><code>nek --export &lt;会话文件&gt; [输出]</code></td><td>在命令行把会话文件导出为 HTML</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">分享前请检查</p><p>导出或分享的会话可能包含提示词、工具参数、命令输出、文件内容，以及对话中出现过的凭据。</p></div><h2 id="收集诊断信息" tabindex="-1">收集诊断信息 <a class="header-anchor" href="#收集诊断信息" aria-label="Permalink to &quot;收集诊断信息&quot;">​</a></h2><p>遇到终端渲染或对话状态的问题时，输入 <code>/debug</code>。nek 会把当前渲染的终端行和会话消息写到 <code>~/.nek/agent/nek-debug.log</code>。这个文件可能包含提示词、回复、工具输出和文件内容，分享前请检查。</p><h2 id="终端兼容性" tabindex="-1">终端兼容性 <a class="header-anchor" href="#终端兼容性" aria-label="Permalink to &quot;终端兼容性&quot;">​</a></h2><p>不同终端对鼠标、修饰键和内嵌图片的支持不同。遇到 <code>Shift+Enter</code> 不换行、<code>Alt+Enter</code> 无效、图片不显示、输入法候选框位置不对等问题，见 <a href="/nekcode/platform/terminal-setup">终端设置</a>。<code>/hotkeys</code> 列出当前生效的全部快捷键，修改方法见 <a href="/nekcode/reference/keybindings">快捷键</a>。</p>',65)])])}const k=t(c,[["render",r]]);export{u as __pageData,k as default};
